INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/anansi', 'Anansi', 'anansi', 'classe-hybride-animal', 37, 5, 0, 5, '- 1 maîtrise Dague
- 1 maîtrise au choix (sauf Dague)', '- Légère
- Bouclier classe 1 à 2', 2, 'Poudre de guérison, breuvage immonde, bloc dégoutant, KDR Arme OU carquois N, panacée mineure', 'Arme Dague Fer et arme en fer selon la maîtrise d''arme', 'Armure de Peau/Cellulose', NULL, NULL, 'Description Anansi', NULL, 'classes', 'Classe Maverick V7 › Anansi › A2:L13, AM1:BA1 ; Classe Maverick V7 › Sommaire › I13:J13', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/arbaletrier', 'Arbalétrier', 'arbaletrier', 'classe-physique-distance', 14, 6, 0, 4, '- 1 maîtrise Arbalète
- 1 maîtrise dans une arme de contact au choix.', '- Légère à Lourde', NULL, 'P fiole jaune, Super Carquois, KDR Armure, Corde (5m), Tête de grappin', 'Arbalète en fer et arme de contact en fer selon la maîtrise', 'Armure de Bois/Argent', NULL, NULL, 'Arbalétrier', 'L’Arbalétrier est un combattant à distance lourd, utilisant des arbalètes pour faire des trous dans les lignes ennemies sans pour autant être trop proche du danger. Précis et destructeur, il maximise l’impact de ses tirs en augmentant leurs dégâts et en perçant les armures ennemies.

Son arme ignore naturellement les défenses physiques et lui exploite au mieux cet avantage. Bien que fait pour la distance, sa lourde armure et sa maîtrise d''une arme de contact lui permettent de se défendre quand son arbalète n''est plus utile.', 'classes', 'Classe Maverick V7 › Arbalètrier › A2:L13, AL1:AZ12 ; Classe Maverick V7 › Sommaire › C3:D3', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/archer', 'Archer', 'archer', 'classe-physique-distance', 13, 6, 2, 2, '- 1 maîtrise Arc
- 1 maîtrise dans une arme de contact au choix.', '- Légère à Intermédiaire
- Bouclier classe 1 à 2', 2, 'P fiole jaune, Super Carquois, KDR Arme, Corde (5m), Tête de grappin', 'Arc en Fer et arme de contact en fer selon la maîtrise', 'Armure de Bois/Acier', NULL, NULL, 'Description Archer', 'L’Archer est un combattant à distance, utilisant arcs pour harceler ses ennemis sans jamais s’exposer directement. Précis et méthodique, il maximise l’impact de ses tirs en augmentant leurs dégâts et en perturbant la défense de ses adversaires.

Son talent lui permet d’exploiter chaque ouverture, rendant l’esquive et la parade plus difficiles pour ses cibles. Capable de s’adapter aux différentes situations de combat, il peut également manier une arme de contact et un bouclier en cas de besoin.', 'classes', 'Classe Maverick V7 › Archer › A2:L13, AL1:AZ12 ; Classe Maverick V7 › Sommaire › C2:D2', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/archimage', 'Archimage', 'archimage', 'classe-speciale', 39, 0, 10, 0, '- 1 maîtrise arme à distance au choix
- 1 maîtrise de Bâton', 'Comment ça une armure ?', NULL, 'P fiole rouge, P fiole verte, torche blanche, bâton magique lvl1, carquois N', 'Arme à distance au choix en fer et Bâton de fer', 'Vêtement de voyage', 'Cette classe est unique au potentiel illimité, vous ne pouvez pas la prendre si vous n''êtes pas du potentiel illimité et est imposée quand vous êtes du potentiel illimité.', NULL, 'Description', 'L’Archimage est la quintessence du pouvoir arcanique, un être qui transcende les limites des mortels pour maîtriser tous les aspects de la magie. Réservée aux individus au Potentiel Illimité, cette classe offre un accès inégalé à la puissance magique. Au plus haut niveau, certains d''entre eux peuvent même exploiter le sang, âme ou corruption.', 'classes', 'Classe Maverick V7 › Archimage › A2:L13, Z2:AH10, AM1:BA15 ; Classe Maverick V7 › Sommaire › K2:L2', NULL, 'magies/potentiel-illimite');
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/barde', 'Barde', 'barde', 'classe-magique', 18, 2, 6, 2, '- 1 maîtrise arme à distance au choix
- 1 maîtrise Dague', '- Légère
- Bouclier classe 1 à 2', 2, 'P fiole mauve, bâton magique lvl1, instrument de musique, carquois N, parchemin vierge (x3)', 'Arme à distance au choix en fer et Dague de fer', 'Armure Cuir/Bois', NULL, NULL, 'Description Barde', 'Le Barde ne se contente pas de chanter, il façonne le combat avec sa musique et ses sorts. Son art inspire ses alliés et perturbe ses ennemis, amplifiant les effets magiques et affaiblissant la concentration adverse.

Avec son instrument comme outil pour sa magie, il accorde ses mélodies aux besoins du combat, renforçant la puissance et les soins tout en semant le trouble chez l’ennemi. Véritable maître de l’harmonie, il transforme chaque affrontement en une symphonie dont il est le métronome.', 'classes', 'Classe Maverick V7 › Barde › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › E3:F3', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/bimane', 'Bimane', 'bimane', 'classe-physique-corps-a-corps', 12, 7, 0, 3, '- 2 maîtrises à répartir dans les armes de corps à corps sans dépasser 1 dans le même', '- Légère à Intermédiaire', NULL, 'P fiole rouge, KDR Arme, pierre à aiguiser, P huile (magie innée), corde (5m)', '2 armes de fer selon les maîtrises choisies', 'Armure de Peau/Fer', NULL, NULL, 'Description Bimane', 'Le Bimane est un expert du combat à deux armes, enchaînant des attaques rapides et dévastatrices sans laisser de répit à ses adversaires. Grâce à sa maîtrise, il réduit considérablement les malus habituellement liés au maniement de deux armes, rendant ses frappes plus efficaces.

Son style repose sur une pression constante, infligeant des dégâts accrus et forçant ses ennemis à l’épuisement. Tâchez de bien viser, ce serait dommage de toucher un allié avec la deuxième arme, hein ?', 'classes', 'Classe Maverick V7 › Bimane › A2:L13, Z1:AH9, AM1:BA12 ; Classe Maverick V7 › Sommaire › A13:B13', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/clerc', 'Clerc', 'clerc', 'classe-magique', 22, 3, 7, 0, '- 1 maîtrise Masse
- 1 maîtrise dans une arme contact au choix (sauf Masse)', '- Légère à Intermédiaire
- Bouclier classe 1 à 2', 2, 'P fiole rouge, poudre de guérison, P fiole bordeaux, bâton magique lvl1, panacée mineure', 'Arme en fer selon la maîtrise', 'Armure de Cellulose/Fer', NULL, NULL, 'Description Clerc', 'Dévoué à sa divinité, le Clerc canalise sa foi pour se protéger et guider ses alliés. Son lien sacré avec sa magie et divinité lui confère une résistance accrue à sa propre magie et lui permet de se rapprocher des volontés divines.

Armé de haches ou de masses consacrées, il équilibre force physique et puissance spirituelle, régénérant mieux son Chakra par la méditation. Inébranlable face aux forces obscures, il se tient prêt à défendre son culte et à abattre les hérétiques d’un coup béni.', 'classes', 'Classe Maverick V7 › Clerc › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › E7:F7', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/cuirasse', 'Cuirassé', 'cuirasse', 'classe-physique-corps-a-corps', 2, 10, 0, 0, '- 1 maîtrise Hast
- 1 maîtrise dans une arme contact au choix (sauf Hast)', '- Légère à Lourde
- Bouclier classe 1 à 5', 5, 'P fiole rouge, KDR Arme, KDR Armure, lingot d''acier, torche', 'Arme en fer selon la maîtrise', 'Armure de Fer/Bronze, Bouclier Rond Corail', 'PROTECTEUR : Le bouclier peut être utilisé comme arme, si jamais vous attaquez avec votre arme principale et que vous enchaînez avec le bouclier, ce dernier fera les dégâts minimum (même en offensif)', NULL, 'Description Cuirassé', 'Le Cuirassé est un rempart vivant, une forteresse de métal avançant inexorablement sur le champ de bataille. Spécialiste des armures lourdes et du combat défensif, il encaisse les assauts avec une résilience inébranlable. 

Maîtrisant l’épée, la masse ou la lance, il adapte son arsenal pour contrer toute menace avec efficacité. Ses parades sont précises, son positionnement optimal, faisant de lui un adversaire redoutable en duel comme en formation. Plus il progresse, plus il devient un mur impénétrable, à tel point qu''il est impossible de l''abattre en un seul coup.', 'classes', 'Classe Maverick V7 › Cuirassé › A2:L13, Z1:AH9, AM1:BA12 ; Classe Maverick V7 › Sommaire › A3:B3', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/fenrir', 'Fenrir', 'fenrir', 'classe-hybride-animal', 27, 8, 2, 0, '- 1 maîtrise Épée
- 1 maîtrise au choix (sauf Épée)', '- Légère
- Bouclier classe 1 à 3', 3, 'Poudre de guérison, breuvage immonde, bloc dégoutant, KDR Arme OU carquois N, pierre à aiguiser', 'Arme épée Fer et arme en fer selon la maîtrise d''arme', 'Armure de Cuir, Targe cuir', NULL, NULL, 'Description Fenrir', 'Le Fenrir est un combattant rusé, utilisant ses instincts surnaturels et sa robustesse pour traquer et éliminer ses ennemis. Sa fourrure épaisse lui confère une résistance naturelle contre les attaques élémentaires de Glace, Foudre et Ombre.

Maître des lames et du pistage, il exploite son sens accru de la perception pour anticiper les dangers et traquer ses proies avec une précision redoutable.', 'classes', 'Classe Maverick V7 › Fenrir › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › I3:J3', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/flagelleur', 'Flagelleur', 'flagelleur', 'classe-hybride', 25, 10, 0, 0, '- 1 maîtrise Masse
- 1 maîtrise dans une arme contact au choix  (sauf Masse)', 'Aucun', NULL, 'Poudre de guérison, P fiole bleue, Corde (5m), Menotte, Bandage (x3)', 'Fouet en Fer ou Arme en fer selon la maîtrise', 'Tenue du Flagelleur', 'La spécialisation "Masochiste" utilise "Concentration" pour lancer ses sortilèges au lieu de "Magie" donc prudence dans la répartition des Caractéristiques. (Dans le cas si on choisit cette classe en premier à une autre classe magique, en deuxième ce changement n''a pas lieu)', NULL, 'Description Flagelleur', 'Le Flagelleur puise sa force dans la souffrance, transformant ses blessures en une source de puissance infinie. Plus il est affaibli, plus ses coups gagnent en force, frappant ses ennemis avec une brutalité exponentielle.

Sans armure, il compte sur son endurance et sa capacité à se soigner en purifiant ses altérations d’état. Chaque cicatrice est une preuve de sa résistance. Il avance sur le champ de bataille avec une détermination frôlant la folie, inspirant l''hésitation sur ses ennemis.', 'classes', 'Classe Maverick V7 › Flagelleur › A2:L13, Z1:AH9, AM1:BA12 ; Classe Maverick V7 › Sommaire › G2:H2', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/frappeur', 'Frappeur', 'frappeur', 'classe-physique-corps-a-corps', 6, 10, 0, 0, '- 2 maîtrises à répartir entre Masse, Pugilat, Bâton combat (1 maximum dans une seule)', '- Légère à Intermédiaire
- Bouclier classe 1 à 3', 3, 'P fiole rouge, KDR Arme, briquet, lanterne, fiole d''huile', '2 Armes en fer selon les maîtrises', 'Armure de Cuir complète', '*Briser/Casser la posture signifie que l''adversaire n''a plus aucune posture active et est donc incapable de se défendre contre des assauts.', NULL, 'Description Frappeur', 'Le Frappeur est un expert des armes de frappe, spécialisé dans l’art de briser les défenses ennemies. Chaque coup qu’il porte a pour objectif de fissurer armures et os, rendant ses adversaires vulnérables aux assauts suivants. Il manie avec aisance masses, bâtons de combat ou même ses propres poings pour frapper avec force. 

Capable de sacrifier sa garde pour des frappes dévastatrices, il excelle dans les duels d’usure où sa puissance finit par l’emporter. Ne comptez pas trop sur votre armure contre un frappeur.', 'classes', 'Classe Maverick V7 › Frappeur › A2:L13, Z2:AH10, AM1:BA12 ; Classe Maverick V7 › Sommaire › A7:B7', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/goleois', 'Goleois', 'goleois', 'classe-hybride-animal', 38, 5, 0, 5, '- 1 maîtrise Pugilat
- 1 maîtrise au choix (sauf Pugilat )', '- Légère
- Bouclier classe 1 à 3', 3, 'Poudre de guérison, breuvage immonde, bloc dégoutant, KDR Arme OU carquois N, corde (5m)', 'Arme Pugilat Fer et arme en fer selon la maîtrise d''arme', 'Armure de Peau/Cellulose', 'Le gameplay de rage se retrouve aussi chez le Martiale, les effets positif et négatif se combinent entre eux. Mais par contre la durée, elle, ne se cumule pas.

Un chant à la fois.', NULL, 'Description Goleois', NULL, 'classes', 'Classe Maverick V7 › Goleois › A2:L13, Z1:AH9, AM1:BA1 ; Classe Maverick V7 › Sommaire › I14:J14', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/grenadier', 'Grenadier', 'grenadier', 'classe-physique-distance', 16, 7, 3, 0, '- 1 maîtrise Bombe
- 1 maîtrise dans une arme contact au choix', '- Légère
- Bouclier classe 1 à 2', 2, 'P fiole jaune, P fiole rouge, briquet, lanterne, fiole huile noire (x2)', 'Bombe en Fer (x10) et arme de contact en fer selon la maîtrise', 'Armure de Cuir complète', NULL, NULL, NULL, NULL, 'classes', 'Classe Maverick V7 › Grenadier › A2:L13 ; Classe Maverick V7 › Sommaire › C5:D5', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/guerrier', 'Guerrier', 'guerrier', 'classe-physique-corps-a-corps', 1, 9, 0, 1, '- 1 maîtrise Épée
- 1 maîtrise dans une arme contact au choix  (sauf épée)', '- Légère à Intermédiaire
- Bouclier classe 1 à 5', 5, 'P fiole rouge, KDR Arme, torche, remède fatigue M,  pierre à aiguiser', 'Arme en acier selon la maîtrise', 'Armure de Fer/Corail, Targe de Fer', NULL, NULL, 'Description Guerrier', 'Le Guerrier est un combattant aguerri, maître des armes tranchantes. Endurant et résistant, il excelle dans les affrontements de mêlée grâce à son équipement robuste et sa force. 

Son entraînement lui confère une meilleure maîtrise de ses armes, augmentant sa précision et ses dégâts. Face au danger, il reste inébranlable, totalement insensible à la couardise. Son rôle est d’être le premier en ligne, faire des trous dans les lignes ennemies.', 'classes', 'Classe Maverick V7 › Guerrier › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › A2:B2', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/jackalope', 'Jackalope', 'jackalope', 'classe-hybride-animal', 35, 2, 4, 4, '- 1 maîtrise Épée
- 1 maîtrise au choix (sauf Épée)', '- Légère
- Bouclier classe 1 à 2', 2, 'Poudre de guérison, breuvage immonde, bloc dégoutant, KDR Arme OU carquois N, corde (10m)', 'Arme épée Fer et arme en fer selon la maîtrise d''arme', 'Armure de Cuir/Peau', NULL, NULL, 'Description Jackalope', 'Le Jackalope est un combattant vif et imprévisible, capable de bondir sur ses ennemis avant même qu’ils ne réalisent sa présence. Doté d’une initiative foudroyante, il domine le début des affrontements et garde toujours une longueur d’avance.

Mais derrière cette hyperactivité se cache un instinct de survie affûté : lorsqu’il trouve un moment de répit, il récupère sa vitalité à une vitesse étonnante.', 'classes', 'Classe Maverick V7 › Jackalope › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › I11:J11', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/kitsune', 'Kitsune', 'kitsune', 'classe-hybride-animal', 28, 5, 5, 0, '- 1 maîtrise Arc
- 1 maîtrise au choix (sauf Arc)', '- Légère
- Bouclier classe 1 à 2', 2, 'Poudre de guérison, breuvage immonde, bloc dégoutant, super carquois , remède gel mineur', 'Arme Arc Fer et arme en fer selon la maîtrise d''arme', 'Armure de Cuir/Bois, Bocle bois', NULL, NULL, 'Description Kitsune', 'Furtif et insaisissable, le Kitsune danse sur le fil entre illusion et réalité. Son agilité  lui permettent de déjouer les embuscades et de semer la confusion parmi ses ennemis.

D’un simple geste, il invoque un renard spectral qui trouble l’attention, détournant les regards au moment clé. Rien n’échappe à son œil acéré, et aucun adversaire ne peut se cacher bien longtemps. Il ne frappe jamais au hasard, chaque tir et chaque coup sont placés avec précision.', 'classes', 'Classe Maverick V7 › Kitsune › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › I4:J4', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/lanceur', 'Lanceur', 'lanceur', 'classe-physique-distance', 15, 5, 2, 3, '- 1 maîtrise Arme de jet
- 1 maîtrise dans une arme de contact au choix.', '- Légère
- Bouclier classe 1 à 3', 3, 'P fiole jaune, corde (10m), tête de grappin, torche, sac de pierre', '3* Armes de Jet Lourdes
ou
5* Armes de Jet Légères
*munitions (fer)', 'Armure de Cuir complète, Bouclier rond en bois', NULL, NULL, 'Description Lanceur', 'Le Lanceur est un combattant expert des armes de jet, capable d’infliger des dégâts précis et puissants à distance. Il excelle dans l’art de frapper sans s’exposer, utilisant sa mobilité et son habileté pour dominer le champ de bataille.

Maîtrisant beaucoup de projectiles différents, il peut aussi se défendre au corps à corps avec des armes adaptées à son style. Son talent lui permet d’augmenter l’impact de ses lancers et d’adapter son équipement pour maintenir une pression constante sur ses adversaires.', 'classes', 'Classe Maverick V7 › Lanceur › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › C4:D4', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/lancier', 'Lancier', 'lancier', 'classe-physique-corps-a-corps', 3, 7, 2, 1, '- 1 maîtrise Hast
- 1 maîtrise Arme de jet', '- Légère à Intermédiaire
- Bouclier classe 1 à 4', 4, 'P fiole rouge, KDR Arme, KDR Armure, ruban collant, P huile toxique', 'Lance en acier et Javelot en fer x2', 'Armure de Cuir/Fer', NULL, NULL, 'Description Lancier', 'Le Lancier est un combattant méthodique, spécialiste des armes d’hast et de jet. Grâce à son arme longue, il maintient ses adversaires à distance tout en profitant de sa mobilité pour se défendre et riposter. 

Son expertise lui permet d’attaquer avec précision, aussi bien en mêlée qu’à portée, sans perdre en efficacité. Grâce à son armure intermédiaire, il trouve un équilibre entre défense et vitesse, lui permettant d''exceller dans les combats prolongés. Il saura sanctionner ceux qui seront trop insolents contre lui.', 'classes', 'Classe Maverick V7 › Lancier › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › A4:B4', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/maclier', 'Maclier', 'maclier', 'classe-magique', 23, 4, 5, 1, '- 1 maîtrise arme contact au choix', '- Légère
- Bouclier classe 1 à 5', 5, 'P fiole mauve, bâton magique lvl1, KDR Armure, lingot d''acier, panacée mineure', 'Arme en acier selon la maîtrise', 'Armure de Peau complète et Écu de bois', NULL, NULL, 'Description Maclier', 'Le Maclier est un mage combattant qui allie la puissance du Chakra à l’imposante défense des grands boucliers. Sa technique unique lui permet de se protéger contre des attaques magiques normalement imparables tout en renforçant ses propres capacités défensives.

Capable de neutraliser certains sorts par la parade et d''influer ses sorts dans son bouclier, il excelle dans l’art de la riposte. Son style de combat repose sur une endurance exceptionnelle, absorbant les coups et détournant la puissance adverse pour mieux contre-attaquer.', 'classes', 'Classe Maverick V7 › Maclier › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › E8:F8', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/mage', 'Mage', 'mage', 'classe-magique', 17, 1, 8, 1, '- 1 maîtrise arme à distance au choix
- 1 maîtrise Bâton', '- Bouclier de classe 1 à 2', 2, 'P fiole mauve, bâton magique lvl1, torche blanche, parchemin gravé (sort magie innée), carquois N', 'Arme à distance au choix en fer et Bâton de fer', 'Vêtement de voyage', NULL, NULL, 'Description Mage', 'Le Mage est un expert du Chakra, capable de modeler la réalité à travers ses sorts. Il puise dans son énergie spirituelle pour infliger de lourds dégâts à distance, exploitant sa ou ses magies.

Son style de combat repose sur la puissance et la concentration, renforcée par sa capacité à méditer même sous pression. Faiblement protégé, il compense par plus de sorts et une armure magique plus grande.', 'classes', 'Classe Maverick V7 › Mage › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › E2:F2', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/mage-bleu', 'Mage Bleu', 'mage-bleu', 'classe-magique', 20, 0, 8, 2, '- 1 maîtrise arme au choix', '- Légère
- Bouclier classe 1 à 2', 2, 'P fiole verte, bâton magique lvl1, KDR Arme OU carquois N, torche,  corde (5m)', 'Arme choisie en acier (x10 si arme de jet/bombe)', 'Armure de cuir/bois', 'Cette classe utilise "Concentration" pour lancer ses sortilèges au lieu de "Magie" donc prudence dans la répartition des Caractéristiques. (Dans le cas si on choisit cette classe en premier par rapport à une autre classe magique, en deuxième ce changement n''a pas lieu).
Un potentiel illimité ne peut pas avoir cette classe.
Cette classe commence avec un gros familier.', NULL, 'Description Mage bleu', 'Le Mage Bleu est une classe particulière capable de mimer ses adversaires, de récupérer leurs avantages et de les retourner contre eux. Tout comme les autres mages colorés, il utilise sa volonté pour lancer ses sorts.

Il peut soit augmenter son savoir sur les monstres mais aussi d''avoir un compagnon familier et de ne faire plus qu''un avec ce dernier. Sa versatilité avec les dons des monstres permet de faire de lui un combattant difficile à anticiper.', 'classes', 'Classe Maverick V7 › Mage Bleu › A2:L13, Z2:AH10, AM1:BA12 ; Classe Maverick V7 › Sommaire › E5:F5', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/mage-rouge', 'Mage Rouge', 'mage-rouge', 'classe-magique', 19, 0, 9, 1, '- 1 maîtrise dans une arme de contact au choix.', '- Légère', NULL, 'P fiole verte, bâton magique lvl1, KDR Arme, torche, pierre à aiguiser', 'Arme en acier selon la maîtrise', 'Armure de Peau complète', 'Cette classe utilise "Concentration" pour lancer ses sortilèges au lieu de "Magie" donc prudence dans la répartition des Caractéristiques. (Dans le cas si on choisit cette classe en premier par rapport à une autre classe magique, en deuxième ce changement n''a pas lieu)', NULL, 'Description Mage rouge', 'Le Mage Rouge fusionne l’art du combat rapproché avec la puissance magique, utilisant sa volonté indomptable pour lancer ses sorts au cœur de la mêlée. Contrairement aux mages traditionnels, il ne dépend pas de l''intelligence, mais de la volonté pour canaliser son Chakra.

Capable de frapper en même temps son arme et son sort, ou en perturbant l’esprit de ses adversaires, il impose un rythme imprévisible au combat. Un guerrier magique, simplement.', 'classes', 'Classe Maverick V7 › Mage Rouge › A2:L13, Z2:AH10, AM1:BA12 ; Classe Maverick V7 › Sommaire › E4:F4', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/mage-vert', 'Mage Vert', 'mage-vert', 'classe-magique', 21, 0, 6, 4, '- 1 maîtrise dans une arme de distance au choix.', '- Bouclier de classe 1 à 2', 2, 'P fiole verte, bâton magique lvl1, super carquois, corde (5m), tête de grappin', 'Arme distance au choix en acier (x10 si arme de jet/bombe)', 'Targe en Acier', 'Cette classe utilise "Concentration" pour lancer ses sortilèges au lieu de "Magie" donc prudence dans la répartition des Caractéristiques. (Dans le cas si on choisit cette classe en premier par rapport à une autre classe magique, en deuxième ce changement n''a pas lieu)', NULL, 'Description Mage vert', 'Le Mage Vert fusionne la magie et le combat à distance, utilisant sa volonté inébranlable pour enchanter ses projectiles. Chaque projectile devient un vecteur de puissance magique, combinant précision et destruction.

Contrairement aux mages classiques, il utilise sa volonté inébranlable pour lancer ses sorts. Il peut charger ses projectiles de sorts offensifs et combiner plusieurs effets pour surprendre ses adversaires, faisant de lui un tireur imprévisible et redoutable.', 'classes', 'Classe Maverick V7 › Mage Vert › A2:L13, Z2:AH10, AM1:BA12 ; Classe Maverick V7 › Sommaire › E6:F6', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/marcass', 'Marcass', 'marcass', 'classe-hybride-animal', 36, 5, 0, 5, '- 1 maîtrise Hache
- 1 maîtrise au choix (sauf Hache)', '- Légère
- Bouclier classe 1 à 3', 3, 'Poudre de guérison, breuvage immonde, bloc dégoutant, KDR Arme OU carquois N, KDR Armure', 'Arme Hache Fer et arme en fer selon la maîtrise d''arme', 'Armure de Peau/Cellulose, Targe de cellulose', NULL, NULL, 'Description Marcass', 'Le Marcass est un combattant qui fonce sans hésitation vers ses adversaires, écrasant tout sur son passage avec sa Charge Porcine, qui augmente sa vitesse lorsqu’il s’élance en ligne droite.

Doté d’une résilience hors du commun, il récupère de la vitalité en consommant de la viande avariée, ignorant les effets néfastes qui affligeraient d’autres races. Survivant né, il transforme même les restes en avantage.', 'classes', 'Classe Maverick V7 › Marcass › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › I12:J12', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/martiale', 'Martiale', 'martiale', 'classe-physique-corps-a-corps', 4, 10, 0, 0, '- 1 maîtrise arme contact au choix', '- Légère
- Bouclier classe 1 à 4', 4, 'P fiole rouge, KDR Arme,  remède mineur au choix, torche, briquet', 'Arme en acier selon la maîtrise', 'Armure de Cuir complète', 'Le gameplay de rage se retrouve aussi chez le Goleois, les effets positif et négatif se combinent entre eux. Mais par contre la durée, elle, ne se cumule pas.', NULL, 'Description Martiale', 'Le Martiale est un combattant féroce qui canalise sa rage pour déchaîner une puissance brutale en combat. Son style repose sur des assauts frénétiques, augmentant sa force et son endurance à mesure que la bataille s’intensifie. 

Spécialiste du combat rapproché, il choisit son arme de prédilection et l’utilise avec une efficacité instinctive, surpassant ses adversaires par la pure agressivité. Sa fureur lui permet d’encaisser les coups tout en maintenant une pression constante sur ses ennemis.', 'classes', 'Classe Maverick V7 › Martiale › A2:L13, Z1:AH9, AM1:BA12 ; Classe Maverick V7 › Sommaire › A5:B5', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/medusain', 'Médusain', 'medusain', 'classe-hybride-animal', 34, 0, 3, 7, '- 1 maîtrise Arme Jet
- 1 maîtrise au choix (sauf Arme jet)', '- Légère
- Bouclier classe 1 à 2', 2, 'Poudre de guérison, breuvage immonde, bloc dégoutant, KDR Arme OU carquois N, canne à pêche', 'Arme Jet Fer (x3) et arme en fer selon la maîtrise d''arme', 'Armure de Peau/Corail', NULL, NULL, 'Description Médusain', 'Le Médusain évolue tel un spectre aquatique, utilisant ses tentacules pour entraver ses adversaires. Sa capacité à produire de la lumière fait de lui un guide dans les profondeurs obscures, mais aussi un appât pour piéger ses proies.

Ses attaques ne se contentent pas d’infliger des dégâts : elles prolongent les altérations d’état (variable selon la magie innée), rendant ses victimes toujours plus vulnérables. À mi-chemin entre la patience d’un prédateur et l’inévitabilité d’un courant marin, il submerge lentement ses ennemis dans la douleur.', 'classes', 'Classe Maverick V7 › Médusain › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › I10:J10', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/mercenaire', 'Mercenaire', 'mercenaire', 'classe-physique-corps-a-corps', 9, 6, 4, 0, '- 3 maîtrises à répartir sans dépasser 1 dans le même', '- Légère à Intermédiaire
- Bouclier classe 1 à 3', 3, 'P fiole rouge, KDR Arme OU Carquois N, lanterne, briquet, corde (x5)', '2 armes de fer selon les maîtrises', 'Armure de Cellulose/Fer, Bouclier rond en bois', NULL, NULL, 'Description Mercenaire', 'Le Mercenaire est un combattant polyvalent, capable de s’adapter à n’importe quelle situation grâce à son expérience et son pragmatisme. Habile avec un large éventail d’armes et d’armures, il sait tirer parti de chaque outil à sa disposition pour s''adapter à une situation x ou y.

Son sens de la logistique lui permet de gérer son équipement sans contrainte, toujours prêt à vivre comme un nomade. Il ne suit aucun code autre que le sien, préférant l’efficacité brute aux idéaux rigides. Le plus offrant pourra profiter de ses talents.', 'classes', 'Classe Maverick V7 › Mercenaire › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › A10:B10', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/minotaure', 'Minotaure', 'minotaure', 'classe-hybride-animal', 32, 10, 0, 0, '- 1 maîtrise Masse
- 1 maîtrise au choix (sauf Masse)', '- Légère
- Bouclier classe 1 à 4', 4, 'Poudre de guérison, breuvage immonde, bloc dégoutant, KDR Arme OU carquois N, corde (5m)', 'Arme Masse Fer et arme en fer selon la maîtrise d''arme', 'Armure de cuir complète (pas de vache hein ?)', NULL, NULL, 'Description Minotaure', 'Similaire à l''Orios, le Minotaure est une force brute sur le champ de bataille, écrasant ses ennemis sous des frappes puissantes. Chaque coup qu’il porte est un choc dévastateur, faisant trembler ceux qui osent l’affronter en duel.

Mais sa véritable force réside dans sa charge. Une fois lancé, il fonce droit sur sa cible, la percutant avant de l’enchaîner sous un assaut furieux. Que ce soit à mains nues ou avec une arme massive, il domine le combat par sa férocité et son impact écrasant.', 'classes', 'Classe Maverick V7 › Minotaure › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › I8:J8', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/moine', 'Moine', 'moine', 'classe-physique-corps-a-corps', 5, 6, 2, 2, '- 1 maîtrise Bâton
- 1 maîtrise dans une arme contact au choix (sauf Bâton)', 'Légère', NULL, 'P fiole rouge, P fiole jaune, KDR Arme, panacée mineure, corde (5m)', 'Arme en fer selon la maîtrise', 'Armure de Cuir complète', NULL, NULL, 'Description Moine', 'Le moine est un combattant honorable qui prêche la paix et la bonne parole aux âmes en quête de réponse, la plupart ont la modestie de reconnaître qu’ils ne sont pas des savants, mais ils font simplement de leur mieux pour aider leur prochain.

La majorité d’entre eux ont prêté serment de pauvreté, modestie ainsi que de fidélité envers leur divinité (Divinité innée ou bien Divinité choisie) chacun est libre d’aider les autres ou bien de prier son dieu à sa manière.', 'classes', 'Classe Maverick V7 › Moine › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › A6:B6', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/namazu', 'Namazu', 'namazu', 'classe-hybride-animal', 29, 8, 2, 0, '- 1 maîtrise Hast
- 1 maîtrise au choix (sauf Hast)', '- Légère
- Bouclier classe 1 à 3', 3, 'Poudre de guérison, breuvage immonde, bloc dégoutant, KDR Arme OU Carquois N, canne à pêche', 'Arme Hast Fer et arme en fer selon la maîtrise d''arme', 'Armure de Peau/Corail, Targe cuir', NULL, NULL, 'Description Namazu', 'Le Namazu est un combattant amphibie, maniant le harpon et l’arbalète avec aisance. Son style de combat repose sur la pénétration, infligeant des dégâts d’estoc dévastateurs.

Plus dangereux encore dans l’eau ou sous la pluie, il profite de son environnement pour maximiser ses frappes. Toujours en mouvement, il traque ses adversaires avec l’instinct d’un prédateur, frappant vite et sans laisser d’échappatoire.', 'classes', 'Classe Maverick V7 › Namazu › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › I5:J5', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/ocultomancien', 'Ocultomancien', 'ocultomancien', 'classe-magique', 24, 0, 8, 2, '- 1 maîtrise dans une arme au choix.', '- Bouclier de classe 1', 1, 'P fiole orange, bâton magique lvl1, torche blanche, KDR Arme OU carquois N,  parchemin gravé (sort magie innée)', 'Arme au choix en Fer', 'Bocle corail', 'Le spécialiste permet d''avoir des résistances à des magies, ou alors avoir la possibilité de taper plus fort contre certaines magies, les altérations d''état ne sont pas concernées par ces capacités.', NULL, 'Description Ocultomancien', 'Là où d’autres brûlent leur énergie sans compter, l’Ocultomancien maîtrise l’art de la magie économe et raffinée. Chaque sort qu’il tisse est optimisé, pas d''énergie inutilement gaspillée.

Il perçoit les connexions invisibles entre son environnement et sa magie, exploitant les moindres éléments du décor pour renforcer son efficacité. Véritable stratège mystique, il ne domine pas la magie par la puissance, mais par l’intelligence, rendant chaque sort plus fluide et plus efficace.', 'classes', 'Classe Maverick V7 › Ocultomancien › A2:L13, Z2:AH10, AM1:BA12 ; Classe Maverick V7 › Sommaire › E9:F9', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/olwman', 'Olwman', 'olwman', 'classe-hybride-animal', 31, 1, 6, 3, '- 1 maîtrise Arbalète
- 1 maîtrise au choix (sauf Arbalète)', '- Légère
- Bouclier classe 1 à 2', 2, 'Poudre de guérison, breuvage immonde, bloc dégoutant, super Carquois, parchemin gravé (sort magie innée)', 'Arme Arbalète Fer et arme en fer selon la maîtrise d''arme', 'Armure de Peau, Bocle cuir', 'Si une armure intermédiaire ou lourde est portée, le vol est impossible.', NULL, 'Description Olwman', 'Le Olwman est un expert de la discrétion et de l’observation, évoluant sans un bruit dans l’obscurité. Son vol est totalement silencieux, lui permettant d’approcher ses cibles sans être détecté.

Grâce à sa vision nocturne, il traque ses ennemis là où d’autres seraient aveugles. Armé de son arbalète et de sa masse, il frappe avec précision, disparaissant aussitôt dans l’ombre. Chasseur méthodique et patient, il est le regard perçant qui voit tout… et que personne ne voit venir.', 'classes', 'Classe Maverick V7 › Olwman › A2:L13, Z2:AH10, AM1:BA12 ; Classe Maverick V7 › Sommaire › I7:J7', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/orios', 'Orios', 'orios', 'classe-hybride-animal', 26, 10, 0, 0, '- 1 maîtrise Pugilat
- 1 maîtrise au choix (sauf Pugilat )', '- Légère
- Bouclier classe 1 à 4', 4, 'Poudre de guérison, breuvage immonde, bloc dégoutant, KDR Arme OU carquois N, corde (5m)', 'Arme Pugilat Fer et arme en fer selon la maîtrise d''arme', 'Armure de Peau/Corail, Bouclier rond cuir', NULL, NULL, 'Description Orios', 'L’Orios est un combattant bestial qui domine le corps-à-corps par sa puissance brute et sa présence terrifiante. Chaque coup qu’il porte résonne comme un tambour, écrasant ses ennemis sous la force pure de ses frappes.

Sa présence imposante inspire la peur, réduisant la capacité de ses adversaires à esquiver ou se défendre. Armé de ses poings ou d''une autre arme, il avance sans crainte, brisant les rangs ennemis par la puissance innée de sa race.', 'classes', 'Classe Maverick V7 › Orios › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › I2:J2', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/parleur', 'Parleur', 'parleur', 'classe-physique-corps-a-corps', 11, 0, 0, 10, '- 1 maîtrise dans une arme au choix.', '- Légère
- Bouclier classe 1 à 2', 2, 'P fiole rouge, P fiole jaune, parchemin vierge (x3), plume à graver, KDR Arme OU carquois N', 'Arme en fer selon la maîtrise', 'Armure de Cuir complète', 'Les compétences actives de cette classe ne fonctionnent que contre des créatures douées de conscience.', NULL, 'Description Parleur', 'Le Parleur est un combattant dont l''arme est le verbe, utilisant son charisme pour manipuler ses adversaires plutôt que de les affronter directement. Capable de provoquer, d’intimider ou de convaincre, il influence les décisions et détourne l’attention en sa faveur. 

Ses compétences psychologiques lui permettent d’exploiter les faiblesses mentales de ses cibles, transformant chaque échange en une arme redoutable. Face aux créatures douées de conscience, il peut semer la discorde ou provoquer des réactions qui lui seront utiles.', 'classes', 'Classe Maverick V7 › Parleur › A2:L13, Z2:AH10, AM1:BA12 ; Classe Maverick V7 › Sommaire › A12:B12', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/pugiliste', 'Pugiliste', 'pugiliste', 'classe-physique-corps-a-corps', 10, 8, 0, 2, '- 1 maîtrise Pugilat', '- Légère', NULL, 'P fiole rouge, poudre de guérison, panacée mineure, KDR Arme, bandage', 'Gants/Grèves en Acier', 'Rien', NULL, NULL, 'Description Pugiliste', 'Le Pugiliste est un guerrier dont le corps est sa seule arme, perfectionnée par l’entraînement et l’endurance. Dépourvu d’armure, il mise sur sa rapidité, sa maîtrise des coups et sa capacité à encaisser pour dominer ses adversaires. 

Ses poings d’acier frappent avec une force brute, chaque attaque gagnant en puissance à mesure qu’il progresse. Difficile de désarmer un tel adversaire.', 'classes', 'Classe Maverick V7 › Pugiliste › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › A11:B11', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/rokh', 'Rokh', 'rokh', 'classe-hybride-animal', 30, 3, 5, 2, '- 1 maîtrise Arc
- 1 maîtrise au choix (sauf Arc)', '- Légère
- Bouclier classe 1 à 2', 2, 'Poudre de guérison, breuvage immonde, bloc dégoutant, super carquois, longue-vue', 'Arc Fer et arme en fer selon la maîtrise d''arme', 'Armure de Peau, Bocle cuir', 'Si une armure intermédiaire ou lourde est portée, le vol est impossible.', NULL, 'Description Rokh', 'Le Rokh domine le champ de bataille depuis les hauteurs, combinant précision mortelle et agilité aérienne. Son plumage résistant lui confère une défense naturelle contre les certaines magies, tandis que son instinct de prédateur le rend encore plus efficace en plein vol.

Rapide, il se déplace avec fluidité dans le ciel, esquivant les attaques tout en décochant des flèches fatales.', 'classes', 'Classe Maverick V7 › Rokh › A2:L13, Z2:AH10, AM1:BA12 ; Classe Maverick V7 › Sommaire › I6:J6', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/satyre', 'Satyre', 'satyre', 'classe-hybride-animal', 33, 0, 4, 6, '- 1 maîtrise Bâton
- 1 maîtrise au choix (sauf Bâton)', '- Légère
- Bouclier classe 1 à 2', 2, 'Poudre de guérison, breuvage immonde, bloc dégoutant, KDR Arme OU carquois N, briquet', 'Arme Bâton Fer et arme en fer selon la maîtrise d''arme', 'Armure de Cuir/Cellulose', NULL, NULL, 'Description Satyre', 'Le Satyre est un combattant aussi imprévisible que charmeur, jouant avec l’esprit de ses adversaires autant qu’avec ses armes. Grâce à son charme inné, il détourne l’attention et fait échouer les embuscades, semant la confusion sur le champ de bataille.

Sa laine peut ralentir ses ennemis et les prive de leur vivacité, les transformant en proies faciles. Toujours en mouvement, il danse entre les coups, utilisant autant la provocation que la force pour désorienter ses ennemis.', 'classes', 'Classe Maverick V7 › Satyre › A2:L13, AM1:BA12 ; Classe Maverick V7 › Sommaire › I9:J9', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/tueur', 'Tueur', 'tueur', 'classe-physique-corps-a-corps', 8, 4, 4, 2, '1 maîtrise d''arme au choix', '- Légère
- Bouclier classe 1 à 2', 2, 'P fiole rouge, KDR Arme OU Carquois N, P huile hémophile, P huile toxique, Crochet (x2)', 'Arme en fer selon la maîtrise', 'Armure de Cuir complète', '*Les dégâts sournois sont des dégâts bonus qui sont comptés quand l''attaque est faite sur une cible qui n''est pas attentive. Comme attaquer sur le flanc alors que la cible est face à face avec un adversaire ou plus simplement dans le dos. 
Ces dégâts ne peuvent pas être augmentés par un bonus, ne sont pas soumis à la posture offensive, ne sont pas comptés dans le coup critique, ne sont JAMAIS élémentaires et ne s''activent que sur une seule attaque.', NULL, 'Description Tueur', 'Le Tueur est un meurtrier opportuniste, spécialisé dans les attaques sournoises et les frappes précises. Il exploite les moments d’inattention pour infliger des dégâts dévastateurs, frappant là où ça fait le plus mal. 

Armé de son arme de prédilection qui peut être autant une arme de contact que distance. Capable de détourner l’attention de ses ennemis pour créer des ouvertures, il excelle dans les combats où la surprise est de mise. Ne perdez jamais de vue, vous pourriez le regretter.', 'classes', 'Classe Maverick V7 › Tueur › A2:L13, Z2:AH11, AM1:BA12 ; Classe Maverick V7 › Sommaire › A9:B9', NULL, NULL);
INSERT INTO classe (id, nom, nom_cle, categorie_id, ordre, sante_depart, chakra_depart, barriere_depart, maitrise_arme, maitrise_armure, bouclier_classe_max, inventaire_depart, arme_depart, armure_depart, chose_a_savoir, chose_a_savoir_lien, description_titre, description, origine, source_ref, remarque, magie_innee_id) VALUES ('classes/voleur', 'Voleur', 'voleur', 'classe-physique-corps-a-corps', 7, 5, 4, 1, '- 1 maîtrise Dague
- 1 maîtrise dans une arme contact au choix (sauf Dague)', '- Légère
- Bouclier classe 1 à 2', 2, 'P fiole rouge, Kit du petit filou, KDR Arme, Corde (x5), 10 ricken d''or', 'Arme en acier selon la maîtrise', 'Armure de Cuir complète', 'Passer en "discret" au combat consomme 2IC au lieu de 3.', NULL, 'Description Voleur', 'Le Voleur est un maître de la discrétion et de la ruse, frappant dans l’ombre avant de disparaître sans laisser de trace. Spécialiste des attaques discrètes, il exploite chaque ouverture pour infliger des dégâts bonus.

Sa ruse et son ingéniosité lui permettent non seulement de contourner ses adversaires, mais aussi de crocheter les coffres, ouvrir les portes et déjouer les pièges. Mais bon … tout est légal tant qu’on ne fait pas attraper non ?', 'classes', 'Classe Maverick V7 › Voleur › A2:L13, Z2:AH10, AM1:BA14 ; Classe Maverick V7 › Sommaire › A8:B8', NULL, NULL);
